using Lorcaire.Application.Notes.DeleteNote;using Lorcaire.Application.Notes.Persistence;using Lorcaire.Application.Notes.UpdateNote;using Lorcaire.Core.Domain.Areas;using Lorcaire.Core.Domain.Notes;
namespace Lorcaire.Application.Tests.Notes;
public sealed class DeleteNoteHandlerTests{[Fact]public async Task DeleteWorks_AndMissingIsReported(){var n=new Note(NoteId.New(),AreaId.New(),"Title","Body",DateTimeOffset.UtcNow);var r=new Repo(n);await new DeleteNoteHandler(r).HandleAsync(n.Id.Value);await Assert.ThrowsAsync<NoteNotFoundException>(()=>new DeleteNoteHandler(r).HandleAsync(n.Id.Value));}private sealed class Repo(params Note[]v):INoteRepository{private readonly Dictionary<NoteId,Note>d=v.ToDictionary(x=>x.Id);public Task AddAsync(Note n,CancellationToken c=default){d.Add(n.Id,n);return Task.CompletedTask;}public Task<Note?>GetByIdAsync(NoteId id,CancellationToken c=default){d.TryGetValue(id,out var n);return Task.FromResult(n);}public Task UpdateAsync(Note n,CancellationToken c=default){d[n.Id]=n;return Task.CompletedTask;}public Task<bool>DeleteAsync(NoteId id,CancellationToken c=default)=>Task.FromResult(d.Remove(id));}}
